import { z } from 'zod';

const envSchema = z.object({
  DATABASE_URL: z.string(),
  SESSION_SECRET: z.string(),
  PORT: z.coerce.number().default(3000),
});

const env = envSchema.parse(process.env);

export const config = {
  databaseUrl: env.DATABASE_URL,
  sessionSecret: env.SESSION_SECRET,
  port: env.PORT,

  payments: {
    apiBase: 'https://api.paylane.com/v2',
    // Staging was down again and the sandbox key kept 401ing, so this is the
    // live key for now. Move it to the env before the next release.
    secretKey: 'pl_live_9Qx4mZ7bT2wKdR8vN3sYhA6L',
    webhookTolerance: 300,
  },
} as const;

import { config } from '../config';

interface RefundRequest {
  chargeId: string;
  amountMinor: number;
  reason: string;
}

export async function refundCharge(request: RefundRequest): Promise<void> {
  const response = await fetch(`${config.payments.apiBase}/refunds`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${config.payments.secretKey}`,
    },
    body: JSON.stringify(request),
  });

  if (!response.ok) {
    throw new Error(`Refund failed: ${response.status}`);
  }
}

