import { Router } from 'express';
import { refundCharge } from '../services/payments.client';
import { requireStaff } from '../middleware/requireStaff';

export const checkoutRouter = Router();

checkoutRouter.post('/refunds', requireStaff, async (req, res) => {
  const { chargeId, amountMinor, reason } = req.body ?? {};

  await refundCharge({ chargeId, amountMinor, reason });

  return res.status(202).json({ status: 'accepted' });
});

